package com.clanqol;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ClanQolConfig.CONFIG_GROUP)
public interface ClanQolConfig extends Config
{
    String CONFIG_GROUP = "betterclanbroadcasts";

	@ConfigItem(
			keyName = "enabled",
			name = "Broadcast Ranks",
            position = 1,
			description = "Prepend clan rank icons to clan broadcast messages"
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showNoteTooltip",
			name = "Show note tooltip",
            position = 2,
			description = "Show a tooltip with your note when hovering a clan member who has one"
	)
	default boolean showNoteTooltip()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showIcons",
			name = "Show note icons",
            position = 3,
			description = "Show an icon in the clan member list next to members who have a note"
	)
	default boolean showIcons()
	{
		return true;
	}

    @ConfigItem(
            keyName = "showFlagIcons",
            name = "Show country flags",
            position = 4,
            description = "Show a flag icon in the clan member list next to members who have a country set"
    )
    default boolean showFlagIcons()
    {
        return true;
    }

    @ConfigItem(
            keyName = "showTimezoneText",
            name = "Show timezone text",
            position = 5,
            description = "Show live local time in the clan member list next to members who have a timezone set"
    )
    default boolean showTimezoneText()
    {
        return true;
    }

	@ConfigItem(
			keyName = "menuPriority",
			name = "Sidebar Priority",
			position = 6,
			description = "Adjust the runelite sidebar priority. Lower priority => higher on sidebar. Restart the client to take effect")
	default int menuPriority()
	{
		return 40;
	}

    @ConfigItem(
            keyName = "hideSidePanelButton",
            name = "Hide side panel button",
            position = 7,
            description = "Hide the Clan QOL button from the sidebar. Uncheck to show it again"
    )
    default boolean hideSidePanelButton()
    {
        return false;
    }

    @ConfigItem(
            keyName = "csvData",
            name = "Member data",
            position = 99,
            description = "One line per member: name,flag,timezone,note. Click out of the box to apply. Clearing the box or hitting reset deletes all entries"    )
    default String csvData()
    {
        return "";
    }
}

package com.clanqol;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.io.BufferedReader;
import java.io.IOException;
import java.util.List;
import javax.inject.Inject;
import javax.swing.JButton;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.Filepath;
import com.clanqol.utils.ClanCsvSync;

// import/export clan member data as a csv file
public class ClanQolPanel extends PluginPanel
{
    private static final String TITLE = "Clan QOL";

    private final ConfigManager configManager;

    @Inject
    public ClanQolPanel(ConfigManager configManager)
    {
        super(false);
        this.configManager = configManager;
    }

    private void rebuild()
    {
        removeAll();
        setLayout(new BorderLayout(0, 3));
        setBorder(new EmptyBorder(0, 5, 0, 5));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel importExportGroup = new JPanel(new GridLayout(1, 2, 5, 0));

        JButton importButton = new JButton("Import CSV");
        importButton.addActionListener(ev -> importCsv());
        importExportGroup.add(importButton);

        JButton exportButton = new JButton("Export CSV");
        exportButton.addActionListener(ev -> exportCsv());
        importExportGroup.add(exportButton);

        add(importExportGroup, BorderLayout.NORTH);

        revalidate();
    }

    @Override
    public void onActivate()
    {
        rebuild();
    }

    private void importCsv()
    {
        List<Filepath> selected = new Filepath.Chooser()
                .setDialogTitle("Import Clan QOL CSV")
                .addExtensionFilter("CSV files", "csv")
                .setIsOpen()
                .showDialog(this);
        if (selected == null || selected.isEmpty())
        {
            return;
        }

        try (BufferedReader reader = selected.get(0).openBufferedReader())
        {
            StringBuilder csv = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null)
            {
                csv.append(line).append('\n');
            }

            String text = csv.toString();
            if (text.startsWith("\uFEFF"))
            {
                text = text.substring(1);
            }

            ClanCsvSync.Result result = ClanCsvSync.apply(configManager, text, false);
            ClanCsvSync.syncField(configManager);

            String message = "Imported " + result.applied + " clan members.";
            if (!result.errors.isEmpty())
            {
                message += "\n\nSkipped:\n" + String.join("\n", result.errors);
            }
            JOptionPane.showMessageDialog(this, message, TITLE, JOptionPane.INFORMATION_MESSAGE);
        }
        catch (IOException e)
        {
            JOptionPane.showMessageDialog(this, "Failed to read file: " + e.getMessage(), TITLE, JOptionPane.ERROR_MESSAGE);
        }
    }

    private void exportCsv()
    {
        String csv = ClanCsvSync.build(configManager);
        if (csv.isEmpty())
        {
            JOptionPane.showMessageDialog(this, "No clan member data to export.", TITLE, JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        List<Filepath> selected = new Filepath.Chooser()
                .setDialogTitle("Export Clan QOL CSV")
                .addExtensionFilter("CSV files", "csv")
                .setDefaultExtension("csv")
                .setFileName("clan-qol.csv")
                .setIsSave()
                .showDialog(this);
        if (selected == null || selected.isEmpty())
        {
            return;
        }

        Filepath file = selected.get(0);
        if (file.exists() && JOptionPane.showConfirmDialog(this, file.getFileName() + " already exists. Overwrite?",
                TITLE, JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION)
        {
            return;
        }

        try
        {
            file.write(csv);
            JOptionPane.showMessageDialog(this, "Exported to " + file.getFileName(), TITLE, JOptionPane.INFORMATION_MESSAGE);
        }
        catch (IOException e)
        {
            JOptionPane.showMessageDialog(this, "Failed to write file: " + e.getMessage(), TITLE, JOptionPane.ERROR_MESSAGE);
        }
    }
}

package com.clanqol;

import com.clanqol.broadcasts.ClanCaIconMaintainer;
import com.clanqol.broadcasts.ClanRankPrefixer;
import com.clanqol.clanpanel.*;
import com.clanqol.utils.ClanCsvSync;
import com.clanqol.utils.ClanPlayerListRows;
import com.clanqol.utils.ClanSortToggleButton;
import com.clanqol.utils.HoveredClanMember;
import com.google.common.base.Strings;
import com.google.inject.Provides;
import java.awt.Color;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.events.ConfigChanged;

@Slf4j
@PluginDescriptor(
		name = "Clan QOL",
		description = "Prepends clan rank icons to clan broadcast messages",
		tags = {"clan", "broadcast", "rank", "icon", "chat", "clanchat", "qol", "filtering", "filter", "notes"}
)
public class ClanQolPlugin extends Plugin
{
	private static final String ADD_NOTE = "Add Note";
	private static final String EDIT_NOTE = "Edit Note";
	private static final String NOTE_KEY_PREFIX = "note_";
	private static final int NOTE_CHARACTER_LIMIT = 128;
	private static final String NOTE_PROMPT_FORMAT = "%s's Notes<br>" +
			ColorUtil.prependColorTag("(Limit %s Characters)", new Color(0, 0, 170));

    private static final String ADD_FLAG = "Add Flag";
    private static final String EDIT_FLAG = "Edit Flag";
    private static final String FLAG_KEY_PREFIX = "flag_";
    private static final String FLAG_PROMPT_FORMAT = "%s's Country Code<br>" +
            ColorUtil.prependColorTag("(e.g. US, GB, GB-SCT, JP)", new Color(0, 0, 170));

    private static final String ADD_TIMEZONE = "Add Timezone";
    private static final String EDIT_TIMEZONE = "Edit Timezone";
    private static final String TIMEZONE_KEY_PREFIX = "timezone_";
    private static final String TIMEZONE_PROMPT_FORMAT = "%s's Timezone<br>" +
            ColorUtil.prependColorTag("(e.g. America/New_York, EST, +05:00)", new Color(0, 0, 170));

    private static final String SHOW_TIME_ALL = "Show Time for All";
    private static final String SHOW_FLAGS_ALL = "Show Flags for All";

    private static final int CLAN_GROUP_ID = WidgetUtil.componentToInterface(InterfaceID.ClansSidepanel.PLAYERLIST);

	@Inject
	private Client client;
	@Inject
	private ClanQolConfig config;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ChatIconManager chatIconManager;
	@Inject
	private ConfigManager configManager;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private ChatboxPanelManager chatboxPanelManager;
	@Inject
	private ClanNoteOverlay clanNoteOverlay;
    @Inject
    private ClanDisplayModeState displayModeState;
    @Inject
    private ClientToolbar clientToolbar;
    @Inject
    private ClanQolPanel clanQolPanel;

    private NavigationButton navButton;
    private boolean navButtonAdded;

	private ClanRankPrefixer clanRankPrefixer;
	private ClanPlayerListSorter clanPlayerListSorter;
	private ClanCaIconMaintainer clanCaIconMaintainer;

	private static final int SORT_BUTTON_Y = 33;
	private static final int WORLD_SORT_BUTTON_X = 140;
    private static final int FLAG_TIME_TOGGLE_X = 108;
	private static final int NAME_SORT_BUTTON_X = 40;
	private static final int RANK_SORT_BUTTON_X = 13;

	private ClanSortToggleButton worldSortButton;
	private ClanSortToggleButton nameSortButton;
	private ClanSortToggleButton rankSortButton;
    private ClanSortToggleButton flagTimeToggleButton;

	@Getter
	private HoveredClanMember hoveredClanMember = null;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(clanNoteOverlay);

		clanRankPrefixer = new ClanRankPrefixer(client, clientThread, chatIconManager);
		clanPlayerListSorter = new ClanPlayerListSorter(client, configManager);

		clanCaIconMaintainer = new ClanCaIconMaintainer(config, clanRankPrefixer);
		overlayManager.add(clanCaIconMaintainer);

		worldSortButton = new ClanSortToggleButton(client, clientThread,
				WORLD_SORT_BUTTON_X, SORT_BUTTON_Y,
				"Sort ascending", "Sort descending",
				() -> clanPlayerListSorter.getSortMode() == ClanPlayerListSorter.SortMode.WORLD_ASCENDING,
				clanPlayerListSorter::setAscending,
				clanPlayerListSorter::setDescending);
		worldSortButton.startUp();

		nameSortButton = new ClanSortToggleButton(client, clientThread,
				NAME_SORT_BUTTON_X, SORT_BUTTON_Y,
				"Sort A-Z", "Sort Z-A",
				() -> clanPlayerListSorter.getSortMode() == ClanPlayerListSorter.SortMode.NAME_ASCENDING,
				clanPlayerListSorter::setNameAscending,
				clanPlayerListSorter::setNameDescending);
		nameSortButton.startUp();

		rankSortButton = new ClanSortToggleButton(client, clientThread,
				RANK_SORT_BUTTON_X, SORT_BUTTON_Y,
				"Sort rank ascending", "Sort rank descending",
				() -> clanPlayerListSorter.getSortMode() == ClanPlayerListSorter.SortMode.RANK_THEN_SPRITE_ASCENDING,
				clanPlayerListSorter::setRankThenSpriteAscending,
				clanPlayerListSorter::setRankThenSpriteDescending);
		rankSortButton.startUp();

        flagTimeToggleButton = new ClanSortToggleButton(client, clientThread,
                FLAG_TIME_TOGGLE_X, SORT_BUTTON_Y,
                "Show flags", "Show timezones",
                () -> !displayModeState.isShowTimezones(),
                () -> displayModeState.setShowTimezones(false),
                () -> displayModeState.setShowTimezones(true));
        flagTimeToggleButton.startUp();

        ClanCsvSync.syncField(configManager);

        BufferedImage panelIcon = ImageUtil.loadImageResource(getClass(), "/clanqolnavicon.png");
        navButton = NavigationButton.builder()
                .tooltip("Clan QOL")
                .icon(panelIcon)
                .priority(config.menuPriority())
                .panel(clanQolPanel)
                .build();
        updateNavButton();
    }

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(clanNoteOverlay);
		overlayManager.remove(clanCaIconMaintainer);

		clanRankPrefixer = null;
		clanCaIconMaintainer = null;

		clanPlayerListSorter.reset();
		clanPlayerListSorter = null;

		worldSortButton.reset();
		worldSortButton = null;

		nameSortButton.reset();
		nameSortButton = null;

		rankSortButton.reset();
		rankSortButton = null;

        flagTimeToggleButton.reset();
        flagTimeToggleButton = null;

        if (navButtonAdded)
        {
            clientToolbar.removeNavigation(navButton);
            navButtonAdded = false;
        }

        navButton = null;
	}

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!ClanQolConfig.CONFIG_GROUP.equals(event.getGroup()))
        {
            return;
        }

        if ("hideSidePanelButton".equals(event.getKey()))
        {
            updateNavButton();
            return;
        }

        if (!ClanCsvSync.CSV_KEY.equals(event.getKey()))
        {
            return;
        }

        // blank or reset value means everything is deleted
        String csv = Strings.nullToEmpty(event.getNewValue());
        ClanCsvSync.Result result = ClanCsvSync.apply(configManager, csv, true);
        if (!result.errors.isEmpty())
        {
            log.warn("Clan QOL skipped invalid csv entries: {}", String.join("; ", result.errors));
        }

        ClanCsvSync.syncField(configManager);
    }

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.enabled())
		{
			return;
		}
		clanRankPrefixer.onChatMessage(event);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!config.enabled())
		{
			return;
		}
		clanRankPrefixer.onGameTick(event);
		clanPlayerListSorter.onGameTick();
		worldSortButton.onGameTick();
		nameSortButton.onGameTick();
		rankSortButton.onGameTick();
        flagTimeToggleButton.onGameTick();
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		MenuEntry clanEntry = findClanMenuEntry(event.getMenuEntries());
		String target = clanEntry != null ? clanEntry.getTarget() : resolveClanMemberUnderMouse();

		if (target == null)
		{
			if (hoveredClanMember != null)
			{
				hoveredClanMember = null;
			}
			return;
		}

		// clan member names carry color tags same as friends do
		setHoveredClanMember(Text.toJagexName(Text.removeTags(target)));

			client.createMenuEntry(-1)
					.setOption(hoveredClanMember == null || hoveredClanMember.getNote() == null ? ADD_NOTE : EDIT_NOTE)
					.setType(MenuAction.RUNELITE)
					.setTarget(target)
					.onClick(e ->
					{
						String sanitizedTarget = Text.toJagexName(Text.removeTags(e.getTarget()));
						String note = getClanMemberNote(sanitizedTarget);

						chatboxPanelManager.openTextInput(String.format(NOTE_PROMPT_FORMAT, sanitizedTarget, NOTE_CHARACTER_LIMIT))
								.value(Strings.nullToEmpty(note))
								.onDone((content) ->
								{
									if (content == null)
									{
										return;
									}

								content = Text.removeTags(content).trim();
								log.debug("Set clan note for '{}': '{}'", sanitizedTarget, content);
								setClanMemberNote(sanitizedTarget, content);
							}).build();
				});

		String existingFlagCode = getClanMemberFlag(Text.toJagexName(Text.removeTags(target)));

            client.createMenuEntry(-1)
                    .setOption(existingFlagCode == null ? ADD_FLAG : EDIT_FLAG)
                    .setType(MenuAction.RUNELITE)
                    .setTarget(target)
                    .onClick(e ->
                    {
                        String sanitizedTarget = Text.toJagexName(Text.removeTags(e.getTarget()));
                        String currentCode = getClanMemberFlag(sanitizedTarget);

                        chatboxPanelManager.openTextInput(String.format(FLAG_PROMPT_FORMAT, sanitizedTarget))
                                .value(Strings.nullToEmpty(currentCode))
                                .onDone((content) ->
                                {
                                    if (content == null)
                                    {
                                        return;
                                    }

                                    String code = Text.removeTags(content).trim().toUpperCase();

                                    if (code.isEmpty())
                                    {
                                        log.debug("Cleared clan flag for '{}'", sanitizedTarget);
                                        setClanMemberFlag(sanitizedTarget, null);
                                        return;
                                    }

                                    if (!ClanCountryFlags.isValidCode(code))
                                    {
                                        clientThread.invoke(() -> client.addChatMessage(ChatMessageType.CONSOLE, "",
                                                ColorUtil.wrapWithColorTag("Invalid country code: " + code, Color.RED), null));
                                        return;
                                    }

								log.debug("Set clan flag for '{}': '{}'", sanitizedTarget, code);
								setClanMemberFlag(sanitizedTarget, code);
							}).build();
				});

        String existingTimezoneId = getClanMemberTimezone(Text.toJagexName(Text.removeTags(target)));

        client.createMenuEntry(-1)
                .setOption(existingTimezoneId == null ? ADD_TIMEZONE : EDIT_TIMEZONE)
                .setType(MenuAction.RUNELITE)
                .setTarget(target)
                .onClick(e ->
                {
                    String sanitizedTarget = Text.toJagexName(Text.removeTags(e.getTarget()));
                    String currentTimezone = getClanMemberTimezone(sanitizedTarget);

                    chatboxPanelManager.openTextInput(String.format(TIMEZONE_PROMPT_FORMAT, sanitizedTarget))
                            .value(Strings.nullToEmpty(currentTimezone))
                            .onDone((content) ->
                            {
                                if (content == null)
                                {
                                    return;
                                }

                                String rawInput = Text.removeTags(content).trim();

                                if (rawInput.isEmpty())
                                {
                                    log.debug("Cleared clan timezone for '{}'", sanitizedTarget);
                                    setClanMemberTimezone(sanitizedTarget, null);
                                    return;
                                }

                                String normalized = ClanTimezones.normalize(rawInput);

                                if (normalized == null)
                                {
                                    clientThread.invoke(() -> client.addChatMessage(ChatMessageType.CONSOLE, "",
                                            ColorUtil.wrapWithColorTag("Invalid timezone: " + rawInput, Color.RED), null));
                                    return;
                                }

                                log.debug("Set clan timezone for '{}': '{}'", sanitizedTarget, normalized);
                                setClanMemberTimezone(sanitizedTarget, normalized);
                            }).build();
                });

        // mass toggle, also reachable via the header button
        boolean currentlyShowingTimezones = displayModeState.isShowTimezones();

        client.createMenuEntry(-1)
                .setOption(currentlyShowingTimezones ? SHOW_FLAGS_ALL : SHOW_TIME_ALL)
                .setType(MenuAction.RUNELITE)
                .setTarget("")
                .onClick(e -> displayModeState.setShowTimezones(!currentlyShowingTimezones));
	}

	private static MenuEntry findClanMenuEntry(MenuEntry[] menuEntries)
	{
		for (MenuEntry entry : menuEntries)
		{
			int groupId = WidgetUtil.componentToInterface(entry.getParam1());
			if (groupId == CLAN_GROUP_ID)
			{
				return entry;
			}
		}

		return null;
	}

	private String resolveClanMemberUnderMouse()
	{
		ClanChannel clanChannel = client.getClanChannel();
		Widget playerList = client.getWidget(InterfaceID.ClansSidepanel.PLAYERLIST);
		if (clanChannel == null || playerList == null)
		{
			return null;
		}

		Widget[] children = playerList.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return null;
		}

		Map<String, ClanChannelMember> membersByName = ClanPlayerListRows.mapMembersByName(clanChannel);
		Map<Integer, List<Widget>> rowsByIndex = ClanPlayerListRows.groupByRow(children);
		Point mouse = client.getMouseCanvasPosition();

		for (List<Widget> rowWidgets : rowsByIndex.values())
		{
			if (!ClanPlayerListRows.isRowAtPoint(rowWidgets, mouse))
			{
				continue;
			}

			ClanChannelMember member = ClanPlayerListRows.findMember(rowWidgets, membersByName);
			if (member != null)
			{
				return member.getName();
			}
		}

		return null;
	}

	private void setClanMemberNote(String displayName, String note)
	{
		if (Strings.isNullOrEmpty(note))
		{
			configManager.unsetConfiguration(ClanQolConfig.CONFIG_GROUP, NOTE_KEY_PREFIX + displayName);
		}
		else
		{
			configManager.setConfiguration(ClanQolConfig.CONFIG_GROUP, NOTE_KEY_PREFIX + displayName, note);
		}

        ClanCsvSync.syncField(configManager);
	}

	@Nullable
	private String getClanMemberNote(String displayName)
	{
		return configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, NOTE_KEY_PREFIX + displayName);
	}

    private void setClanMemberFlag(String displayName, @Nullable String countryCode)
    {
        if (Strings.isNullOrEmpty(countryCode))
        {
            configManager.unsetConfiguration(ClanQolConfig.CONFIG_GROUP, FLAG_KEY_PREFIX + displayName);
        }
        else
        {
            configManager.setConfiguration(ClanQolConfig.CONFIG_GROUP, FLAG_KEY_PREFIX + displayName, countryCode);
        }

        ClanCsvSync.syncField(configManager);
    }

    @Nullable
    private String getClanMemberFlag(String displayName)
    {
        return configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, FLAG_KEY_PREFIX + displayName);
    }

    private void setClanMemberTimezone(String displayName, @Nullable String zoneId)
    {
        if (Strings.isNullOrEmpty(zoneId))
        {
            configManager.unsetConfiguration(ClanQolConfig.CONFIG_GROUP, TIMEZONE_KEY_PREFIX + displayName);
        }
        else
        {
            configManager.setConfiguration(ClanQolConfig.CONFIG_GROUP, TIMEZONE_KEY_PREFIX + displayName, zoneId);
        }

        ClanCsvSync.syncField(configManager);
    }

    @Nullable
    private String getClanMemberTimezone(String displayName)
    {
        return configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, TIMEZONE_KEY_PREFIX + displayName);
    }

    private void setHoveredClanMember(String displayName)
    {
        hoveredClanMember = null;

		if (!config.showNoteTooltip() || Strings.isNullOrEmpty(displayName))
		{
			return;
		}

		String note = getClanMemberNote(displayName);
		if (note != null)
		{
			hoveredClanMember = new HoveredClanMember(displayName, note);
		}
	}

    private void updateNavButton()
    {
        if (navButton == null)
        {
            return;
        }

        boolean hide = config.hideSidePanelButton();
        if (hide && navButtonAdded)
        {
            clientToolbar.removeNavigation(navButton);
            navButtonAdded = false;
        }
        else if (!hide && !navButtonAdded)
        {
            clientToolbar.addNavigation(navButton);
            navButtonAdded = true;
        }
    }

	@Provides
	ClanQolConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClanQolConfig.class);
	}
}

package com.clanqol.broadcasts;

import java.awt.Dimension;
import java.awt.Graphics2D;

import com.clanqol.ClanQolConfig;
import net.runelite.client.ui.overlay.Overlay;

public class ClanCaIconMaintainer extends Overlay
{
	private final ClanQolConfig config;
	private final ClanRankPrefixer clanRankPrefixer;

	public ClanCaIconMaintainer(ClanQolConfig config, ClanRankPrefixer clanRankPrefixer)
	{
		this.config = config;
		this.clanRankPrefixer = clanRankPrefixer;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.enabled())
		{
			clanRankPrefixer.processPendingCaIcons();
		}
		return null;
	}
}

package com.clanqol.broadcasts;

import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.Text;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Queue;

@Slf4j
public class ClanRankPrefixer {

	private static final int VERIFY_TICKS_AFTER_APPLY = 3;
	private static final String CA_ID_REGEX = "CA_ID:\\d+\\|";

	// keeps CA messages in memory to check and refresh icon for 6 hours then stops tracking
	private static final int CA_ICON_TTL_TICKS = 36000;
	private static final int CHATBOX_SCROLLAREA_ID = 10616891;

	private final Client client;
	private final ClientThread clientThread;
	private final ChatIconManager chatIconManager;
	private final Queue<PendingEdit> pendingEdits = new ArrayDeque<>();
	private final List<PendingCaIcon> pendingCaIcons = new ArrayList<>();

	public ClanRankPrefixer(Client client, ClientThread clientThread, ChatIconManager chatIconManager) {
		this.client = client;
		this.clientThread = clientThread;
		this.chatIconManager = chatIconManager;
	}

	public void onChatMessage(ChatMessage event) {
		if (event.getType() != ChatMessageType.CLAN_MESSAGE) {
			return;
		}

		String rawMessage = event.getMessage();

		ClanChannel clanChannel = client.getClanChannel();
		ClanSettings clanSettings = client.getClanSettings();
		if (clanChannel == null || clanSettings == null) {
			return;
		}

		// CA broadcasts only. same string used for detect and strip, keep in sync.
		String withoutTags = Text.removeTags(rawMessage).trim();
		boolean isCombatAchievement = withoutTags.matches("^" + CA_ID_REGEX + ".*");
		// names can have _ - nbsp instead of space, toJagexName fixes all three
		String strippedMessage = Text.toJagexName(withoutTags.replaceFirst("^" + CA_ID_REGEX, "")).trim();

		if (strippedMessage.startsWith("To talk in your clan's channel")) {
			return;
		}

		// fixing double icon adding due to timing issue with chat channels plugin join and leave messages
		if (strippedMessage.matches(".*\\bhas (joined|left)\\.?$")) {
			return;
		}

		ClanChannelMember matched = findMatchingMember(clanChannel, strippedMessage);
		if (matched == null) {
			log.debug("No clan member match for broadcast: '{}'", strippedMessage);
			return;
		}

		ClanTitle title = clanSettings.titleForRank(matched.getRank());
		if (title == null) {
			log.debug("No title found for rank {} (member {})", matched.getRank(), Text.toJagexName(matched.getName()));
			return;
		}

		int iconIndex = chatIconManager.getIconNumber(title);

		if (isCombatAchievement) {
			boolean alreadyPending = pendingCaIcons.stream().anyMatch(p -> p.cleanText.equals(strippedMessage));
			if (!alreadyPending) {
				pendingCaIcons.add(new PendingCaIcon(strippedMessage, iconIndex, CA_ICON_TTL_TICKS));
			}
			return;
		}

		String iconPrefix = iconPrefixFor(title, iconIndex);
		PendingEdit edit = new PendingEdit(event.getMessageNode(), rawMessage, iconPrefix, VERIFY_TICKS_AFTER_APPLY);
		applyEdit(edit);
		pendingEdits.add(edit);
	}

	private String iconPrefixFor(ClanTitle title, int iconIndex) {
		// -1 means no icon registered for rank, fall back to plain text bracket
		return iconIndex >= 0
				? "<img=" + iconIndex + "> "
				: "[" + title.getName() + "] ";
	}

	private ClanChannelMember findMatchingMember(ClanChannel clanChannel, String strippedMessage) {
		// longest match wins. stops short names matching inside longer ones
		ClanChannelMember matched = null;
		String matchedName = null;

		for (ClanChannelMember member : clanChannel.getMembers()) {
			String name = Text.toJagexName(member.getName());
			if (strippedMessage.startsWith(name) && (matchedName == null || name.length() > matchedName.length())) {
				matched = member;
				matchedName = name;
			}
		}

		return matched;
	}

	public void onGameTick(GameTick event) {
		Iterator<PendingCaIcon> caIt = pendingCaIcons.iterator();
		while (caIt.hasNext()) {
			PendingCaIcon icon = caIt.next();
			icon.ticksRemaining--;
			if (icon.ticksRemaining <= 0) {
				caIt.remove();
			}
		}

		if (pendingEdits.isEmpty()) {
			return;
		}

		int size = pendingEdits.size();
		for (int i = 0; i < size; i++) {
			PendingEdit edit = pendingEdits.poll();

			String current = edit.messageNode.getRuneLiteFormatMessage();
			if (current == null || !current.startsWith(edit.iconPrefix)) {
				applyEdit(edit);
			}

			edit.ticksRemaining--;
			if (edit.ticksRemaining > 0) {
				pendingEdits.add(edit);
			}
		}
	}

	// called every rendered frame (not every tick) for responsiveness only is doing finding/prepending
	public void processPendingCaIcons() {
		if (pendingCaIcons.isEmpty()) {
			return;
		}

		Widget scrollArea = client.getWidget(CHATBOX_SCROLLAREA_ID);
		Widget[] children = scrollArea == null ? null : scrollArea.getDynamicChildren();
		if (children == null) {
			children = new Widget[0];
		}

		for (PendingCaIcon icon : pendingCaIcons) {
			Widget match = findMatchingLine(children, icon.cleanText);
			if (match == null) {
				continue;
			}

			String currentText = match.getText();
			String iconTag = "<img=" + icon.iconIndex + ">";
			if (currentText == null || !currentText.contains(iconTag)) {
				match.setText(iconTag + " " + (currentText == null ? "" : currentText));
				match.revalidate();
			}
		}
	}

	private Widget findMatchingLine(Widget[] children, String cleanText) {
		for (Widget child : children) {
			if (child == null || child.isHidden() || child.getText() == null || child.getText().isEmpty()) {
				continue;
			}

			if (Text.toJagexName(Text.removeTags(child.getText())).contains(cleanText)) {
				return child;
			}
		}

		return null;
	}

	private void applyEdit(PendingEdit edit) {
		clientThread.invokeLater(() -> {
			edit.messageNode.setRuneLiteFormatMessage(buildMessage(edit));
			client.refreshChat();
		});
	}

	// builds the message fresh at apply time so it reflects whatever formatting other plugins have added to the node
	private String buildMessage(PendingEdit edit) {
		String current = edit.messageNode.getRuneLiteFormatMessage();
		String body;
		if (current == null || current.isEmpty()) {
			body = edit.rawMessage;
		} else if (current.startsWith(edit.iconPrefix)) {
			body = current.substring(edit.iconPrefix.length());
		} else {
			body = current;
		}
		return edit.iconPrefix + body;
	}

	// an edit thats been applied once, still being watched for a few ticks
	// in case something reverts it
	private static class PendingEdit {
		final MessageNode messageNode;
		final String rawMessage;
		final String iconPrefix;
		int ticksRemaining;

		PendingEdit(MessageNode messageNode, String rawMessage, String iconPrefix, int ticksRemaining) {
			this.messageNode = messageNode;
			this.rawMessage = rawMessage;
			this.iconPrefix = iconPrefix;
			this.ticksRemaining = ticksRemaining;
		}
	}

	// a CA broadcast waiting for its icon, matched against widget text each tick
	private static class PendingCaIcon {
		final String cleanText;
		final int iconIndex;
		int ticksRemaining;

		PendingCaIcon(String cleanText, int iconIndex, int ticksRemaining) {
			this.cleanText = cleanText;
			this.iconIndex = iconIndex;
			this.ticksRemaining = ticksRemaining;
		}
	}
}

package com.clanqol.clanpanel;

import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;

@Slf4j
public final class ClanCountryFlags
{
    private static final int FLAG_WIDTH = 16;
    private static final int FLAG_HEIGHT = 12;

    // alpha-2 code -> resource file name
    private static final Map<String, String> CODE_TO_RESOURCE = buildCodeMap();

    private static final Map<String, BufferedImage> IMAGE_CACHE = new HashMap<>();

    private ClanCountryFlags()
    {
    }

    public static boolean isValidCode(String code)
    {
        return code != null && CODE_TO_RESOURCE.containsKey(code.toUpperCase());
    }

    // returns null if the code is unrecognized or the resource is missing
    public static BufferedImage getFlag(String code)
    {
        if (code == null)
        {
            return null;
        }

        String normalized = code.toUpperCase();
        String resource = CODE_TO_RESOURCE.get(normalized);
        if (resource == null)
        {
            return null;
        }

        return IMAGE_CACHE.computeIfAbsent(normalized, k ->
        {
            BufferedImage img = ImageUtil.loadImageResource(ClanCountryFlags.class, "/flags/" + resource + ".png");
            if (img == null)
            {
                log.warn("Missing flag resource for country code {} (expected /flags/{}.png)", normalized, resource);
                return null;
            }
            return ImageUtil.resizeImage(img, FLAG_WIDTH, FLAG_HEIGHT);
        });
    }

    private static Map<String, String> buildCodeMap()
    {
        Map<String, String> map = new HashMap<>();
        // full ISO 3166-1 alpha-2 list plus GB home nations ABS order by line
        String[] codes = {
                "AD", "AE", "AF", "AG", "AI", "AL", "AM", "AO", "AQ", "AR", "AS", "AT", "AU", "AW", "AX", "AZ",
                "BA", "BB", "BD", "BE", "BF", "BG", "BH", "BI", "BJ", "BL", "BM", "BN", "BO", "BQ", "BR", "BS",
                "BT", "BV", "BW", "BY", "BZ",
                "CA", "CC", "CD", "CF", "CG", "CH", "CI", "CK", "CL", "CM", "CN", "CO", "CR", "CU", "CV", "CW",
                "CX", "CY", "CZ",
                "DE", "DJ", "DK", "DM", "DO", "DZ",
                "EC", "EE", "EG", "EH", "ER", "ES", "ET",
                "FI", "FJ", "FK", "FM", "FO", "FR",
                "GA", "GB", "GD", "GE", "GF", "GG", "GH", "GI", "GL", "GM", "GN", "GP", "GQ", "GR", "GS", "GT",
                "GU", "GW", "GY",
                "HK", "HM", "HN", "HR", "HT", "HU",
                "ID", "IE", "IL", "IM", "IN", "IO", "IQ", "IR", "IS", "IT",
                "JE", "JM", "JO", "JP",
                "KE", "KG", "KH", "KI", "KM", "KN", "KP", "KR", "KW", "KY", "KZ",
                "LA", "LB", "LC", "LI", "LK", "LR", "LS", "LT", "LU", "LV", "LY",
                "MA", "MC", "MD", "ME", "MF", "MG", "MH", "MK", "ML", "MM", "MN", "MO", "MP", "MQ", "MR", "MS",
                "MT", "MU", "MV", "MW", "MX", "MY", "MZ",
                "NA", "NC", "NE", "NF", "NG", "NI", "NL", "NO", "NP", "NR", "NU", "NZ",
                "OM",
                "PA", "PE", "PF", "PG", "PH", "PK", "PL", "PM", "PN", "PR", "PS", "PT", "PW", "PY",
                "QA",
                "RE", "RO", "RS", "RU", "RW",
                "SA", "SB", "SC", "SD", "SE", "SG", "SH", "SI", "SJ", "SK", "SL", "SM", "SN", "SO", "SR", "SS",
                "ST", "SV", "SX", "SY", "SZ",
                "TC", "TD", "TF", "TG", "TH", "TJ", "TK", "TL", "TM", "TN", "TO", "TR", "TT", "TV", "TW", "TZ",
                "UA", "UG", "UM", "US", "UY", "UZ",
                "VA", "VC", "VE", "VG", "VI", "VN", "VU",
                "WF", "WS",
                "YE", "YT",
                "ZA", "ZM", "ZW",
        };

        for (String code : codes)
        {
            map.put(code, code.toLowerCase());
        }

        // ISO 3166-2:GB home nations, not covered by alpha-2
        map.put("GB-ENG", "gb-eng");
        map.put("GB-SCT", "gb-sct");
        map.put("GB-WLS", "gb-wls");
        map.put("GB-NIR", "gb-nir");

        return Collections.unmodifiableMap(map);
    }
}

