import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
public class ClanNoteOverlay extends Overlay
{
	private static final int NOTE_ICON_WIDTH = 12;
	private static final int NOTE_ICON_HEIGHT = 12;

    private static final int NOTE_ICON_X = 104;

    private static final int FLAG_ICON_WIDTH = 13;
    private static final int FLAG_ICON_HEIGHT = 12;
    private static final int FLAG_ICON_GAP = 4;
    private static final int TIME_TEXT_X = 116;
    private static final float TIME_FONT_SIZE = 14f;
    private static final int ROW_HEIGHT = 15;
	private final Client client;
	private final ClanQolConfig config;
	private final ConfigManager configManager;
	private final TooltipManager tooltipManager;
    private final ClanDisplayModeState displayModeState;

	private BufferedImage noteIcon;
	private int lastLoggedTick = -1;

	@Inject
	private ClanNoteOverlay(Client client, ClanQolConfig config, ConfigManager configManager,
							TooltipManager tooltipManager, ClanDisplayModeState displayModeState)
	{
		this.client = client;
		this.config = config;
		this.configManager = configManager;
		this.tooltipManager = tooltipManager;
        this.displayModeState = displayModeState;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/noteicon.png");
		if (icon == null)
		{
			log.warn("noteicon.png not found, note icons will not be drawn");
		}
		else
		{
			noteIcon = ImageUtil.resizeImage(icon, NOTE_ICON_WIDTH, NOTE_ICON_HEIGHT);
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ClanChannel clanChannel = client.getClanChannel();
		Widget playerList = client.getWidget(InterfaceID.ClansSidepanel.PLAYERLIST);
		if (clanChannel == null || playerList == null)
		{
			return null;
		}

		Widget[] children = playerList.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return null;
		}

		Map<String, ClanChannelMember> membersByName = ClanPlayerListRows.mapMembersByName(clanChannel);
		Map<Integer, List<Widget>> rowsByIndex = ClanPlayerListRows.groupByRow(children);

		Point playerListCanvasLocation = playerList.getCanvasLocation();
		Rectangle playerListBounds = playerList.getBounds();
		boolean menuOpen = client.isMenuOpen();
		Point mouse = client.getMouseCanvasPosition();
        boolean showTimezones = displayModeState.isShowTimezones();

        Rectangle originalClip = graphics.getClipBounds();
        if (playerListBounds != null)
        {
            graphics.setClip(playerListBounds);
        }

		for (Map.Entry<Integer, List<Widget>> entry : rowsByIndex.entrySet())
		{
			List<Widget> rowWidgets = entry.getValue();
			ClanChannelMember member = ClanPlayerListRows.findMember(rowWidgets, membersByName);
			if (member == null)
			{
				continue;
			}

			String displayName = Text.toJagexName(Text.removeTags(member.getName()));
			String note = configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, "note_" + displayName);
            String flagCode = configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, "flag_" + displayName);
            String timezoneId = configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, "timezone_" + displayName);
            BufferedImage flagImage = !showTimezones && flagCode != null ? ClanCountryFlags.getFlag(flagCode) : null;
            String timeText = showTimezones && timezoneId != null ? ClanTimezones.currentTime(timezoneId) : null;

            if (note == null && flagImage == null && timeText == null)
            {
                continue;
            }

            Point anchorCanvasLocation = rowWidgets.get(0).getCanvasLocation();

            if (anchorCanvasLocation != null && playerListCanvasLocation != null)
            {
                if (!showTimezones && note != null && config.showIcons() && noteIcon != null)
                {
                    int noteX = playerListCanvasLocation.getX() + NOTE_ICON_X;
                    int noteY = anchorCanvasLocation.getY() + (ROW_HEIGHT - NOTE_ICON_HEIGHT) / 2;
                    graphics.drawImage(noteIcon, noteX, noteY, null);
                }

                int flagSlotRightEdge = playerListCanvasLocation.getX() + NOTE_ICON_X - FLAG_ICON_GAP;
                int timeSlotRightEdge = playerListCanvasLocation.getX() + TIME_TEXT_X;
                int rowTop = anchorCanvasLocation.getY();

                if (flagImage != null && config.showFlagIcons())
                {
                    int flagX = flagSlotRightEdge - FLAG_ICON_WIDTH;
                    int flagY = rowTop + (ROW_HEIGHT - FLAG_ICON_HEIGHT) / 2;
                    graphics.drawImage(flagImage, flagX, flagY, null);
                }

                if (timeText != null && config.showTimezoneText())
                {
                    Font originalFont = graphics.getFont();
                    Font timeFont = originalFont.deriveFont(TIME_FONT_SIZE);
                    graphics.setFont(timeFont);

                    FontMetrics metrics = graphics.getFontMetrics(timeFont);
                    int textHeight = metrics.getAscent() + metrics.getDescent();
                    int textX = timeSlotRightEdge - metrics.stringWidth(timeText);
                    int textY = rowTop + (ROW_HEIGHT - textHeight) / 2 + metrics.getAscent();
                    graphics.setColor(Color.WHITE);
                    graphics.drawString(timeText, textX, textY);

                    graphics.setFont(originalFont);
                }
            }

			if (!menuOpen && config.showNoteTooltip() && ClanPlayerListRows.isRowAtPoint(rowWidgets, mouse))
            {
                String prefix = showTimezones ? timeText : flagCode;
                String tooltipText = prefix != null && note != null
                        ? prefix + " - " + note
                        : prefix != null ? prefix : note;
                if (tooltipText != null)
                {
                    tooltipManager.add(new Tooltip(tooltipText));
                }
            }
        }

        graphics.setClip(originalClip);

		return null;
	}
}

package com.clanqol.clanpanel;

import com.clanqol.ClanQolConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Slf4j
public class ClanPlayerListSorter
{
	private static final int CLAN_ROW_HEIGHT = 15;
	private static final String SORT_MODE_CONFIG_KEY = "sortMode";

	private final Client client;
	private final ConfigManager configManager;

	private final Map<Widget, Integer> nativeWidgetYs = new IdentityHashMap<>();

	public enum SortMode
	{
		NONE,
		WORLD_ASCENDING,
		WORLD_DESCENDING,
		NAME_ASCENDING,
		NAME_DESCENDING,
		RANK_THEN_SPRITE_ASCENDING,
		RANK_THEN_SPRITE_DESCENDING
	}

	private SortMode sortMode;

	public ClanPlayerListSorter(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
		this.sortMode = loadSortMode();
	}

	public void setAscending()
	{
		sortMode = SortMode.WORLD_ASCENDING;
		persistSortMode();
	}

	public void setDescending()
	{
		sortMode = SortMode.WORLD_DESCENDING;
		persistSortMode();
	}

	public void setNameAscending()
	{
		sortMode = SortMode.NAME_ASCENDING;
		persistSortMode();
	}

	public void setNameDescending()
	{
		sortMode = SortMode.NAME_DESCENDING;
		persistSortMode();
	}

	public void setRankThenSpriteAscending()
	{
		sortMode = SortMode.RANK_THEN_SPRITE_ASCENDING;
		persistSortMode();
	}

	public void setRankThenSpriteDescending()
	{
		sortMode = SortMode.RANK_THEN_SPRITE_DESCENDING;
		persistSortMode();
	}

	public void clear()
	{
		sortMode = SortMode.NONE;
		persistSortMode();
		restore();
	}

	public boolean isActive()
	{
		return sortMode != SortMode.NONE;
	}

	public SortMode getSortMode()
	{
		return sortMode;
	}

	// call from onGameTick. list gets rebuilt by the client on its own so we
	// gotta keep re-sorting every tick to keep it stable
	public void onGameTick()
	{
		if (sortMode != SortMode.NONE)
		{
			sort();
		}
	}

	// puts widgets back to their native positions, call from shutDown
	public void reset()
	{
		restore();
	}

	private SortMode loadSortMode()
	{
		String saved = configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, SORT_MODE_CONFIG_KEY);
		if (saved == null)
		{
			return SortMode.NAME_ASCENDING;
		}

		try
		{
			return SortMode.valueOf(saved);
		}
		catch (IllegalArgumentException e)
		{
			// saved value doesnt match a current enum constant, e.g. after a
			// plugin update removed/renamed a mode. fall back to the default
			// sort rather than crash
			return SortMode.NAME_ASCENDING;
		}
	}

	private void persistSortMode()
	{
		configManager.setConfiguration(ClanQolConfig.CONFIG_GROUP, SORT_MODE_CONFIG_KEY, sortMode.name());
	}

	private void sort()
	{
		ClanChannel clanChannel = client.getClanChannel();
		Widget playerList = client.getWidget(InterfaceID.ClansSidepanel.PLAYERLIST);
		if (clanChannel == null || playerList == null)
		{
			return;
		}

		Widget[] children = playerList.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			return;
		}

		Map<String, ClanChannelMember> membersByName = new HashMap<>();
		for (ClanChannelMember member : clanChannel.getMembers())
		{
			membersByName.put(normalizeName(member.getName()), member);
		}

		// group by row index instead of exact y match. the rank icon widget's y
		// can be off by 1px from the name/world widgets in the same row, so an
		// exact match splits it into its own row with nothing to identify a
		// member, gets dropped, and stays behind when the rest of the row moves
		Map<Integer, ClanPlayerRow> rowsByIndex = new LinkedHashMap<>();
		Map<Widget, Integer> currentNativeWidgetYs = new IdentityHashMap<>();
		for (Widget child : children)
		{
			if (child == null || child.isHidden())
			{
				continue;
			}

			currentNativeWidgetYs.put(child,
					nativeWidgetYs.getOrDefault(child, child.getOriginalY()));
			int rowIndex = Math.round(child.getOriginalY() / (float) CLAN_ROW_HEIGHT);
			rowsByIndex.computeIfAbsent(rowIndex, ClanPlayerRow::new)
					.widgets.add(child);
		}

		nativeWidgetYs.clear();
		nativeWidgetYs.putAll(currentNativeWidgetYs);

		List<ClanPlayerRow> rows = new ArrayList<>();
		for (ClanPlayerRow row : rowsByIndex.values())
		{
			row.member = findMember(row, membersByName);
			if (row.member != null)
			{
				rows.add(row);
			}
		}

		switch (sortMode)
		{
			case WORLD_ASCENDING:
				rows.sort(Comparator
						.comparingInt((ClanPlayerRow row) -> row.member.getWorld())
						.thenComparing(row -> row.member.getName(), String.CASE_INSENSITIVE_ORDER)
						.thenComparingInt(row -> row.rowIndex));
				break;
			case WORLD_DESCENDING:
				rows.sort(Comparator
						.comparingInt((ClanPlayerRow row) -> row.member.getWorld()).reversed()
						.thenComparing(row -> row.member.getName(), String.CASE_INSENSITIVE_ORDER)
						.thenComparingInt(row -> row.rowIndex));
				break;
			case NAME_ASCENDING:
				rows.sort(Comparator
						.comparing((ClanPlayerRow row) -> row.member.getName(), String.CASE_INSENSITIVE_ORDER)
						.thenComparingInt(row -> row.member.getWorld())
						.thenComparingInt(row -> row.rowIndex));
				break;
			case NAME_DESCENDING:
				rows.sort(Comparator
						.comparing((ClanPlayerRow row) -> row.member.getName(), String.CASE_INSENSITIVE_ORDER).reversed()
						.thenComparingInt(row -> row.member.getWorld())
						.thenComparingInt(row -> row.rowIndex));
				break;
			case RANK_THEN_SPRITE_ASCENDING:
				rows.sort(buildRankThenSpriteComparator());
				break;
			case RANK_THEN_SPRITE_DESCENDING:
				rows.sort(buildRankThenSpriteComparator().reversed());
				break;
			case NONE:
			default:
				break;
		}

		for (int index = 0; index < rows.size(); index++)
		{
			int newY = index * CLAN_ROW_HEIGHT;
			for (Widget widget : rows.get(index).widgets)
			{
				widget.setOriginalY(newY);
				widget.revalidate();
			}
		}
	}

	private Comparator<ClanPlayerRow> buildRankThenSpriteComparator()
	{
		// rank is -1 (guest) to 127 (jmod), reversed so highest rank comes first as the base order
		return Comparator
				.comparingInt((ClanPlayerRow row) -> row.member.getRank().getRank()).reversed()
				.thenComparingInt(this::findSpriteId)
				.thenComparing(row -> row.member.getName(), String.CASE_INSENSITIVE_ORDER)
				.thenComparingInt(row -> row.rowIndex);
	}

	private int findSpriteId(ClanPlayerRow row)
	{
		for (Widget widget : row.widgets)
		{
			if (widget.getSpriteId() > -1)
			{
				return widget.getSpriteId();
			}
		}

		// no icon widget in this row, probably unranked/guest. sort it last
		// instead of throwing off the whole comparator
		return Integer.MAX_VALUE;
	}

	private ClanChannelMember findMember(ClanPlayerRow row,
										 Map<String, ClanChannelMember> membersByName)
	{
		for (Widget widget : row.widgets)
		{
			// some widgets carry the rsn in getName() with a col tag instead of
			// getText(), which can be blank. check both so we dont silently drop
			// the whole row
			ClanChannelMember member = membersByName.get(normalizeName(widget.getText()));
			if (member != null)
			{
				return member;
			}

			member = membersByName.get(normalizeName(widget.getName()));
			if (member != null)
			{
				return member;
			}
		}

		return null;
	}

	private static String normalizeName(String name)
	{
		return name == null ? "" : Text.toJagexName(Text.removeTags(name)).toLowerCase();
	}

	private void restore()
	{
		for (Map.Entry<Widget, Integer> entry : nativeWidgetYs.entrySet())
		{
			Widget widget = entry.getKey();
			widget.setOriginalY(entry.getValue());
			widget.revalidate();
		}
		nativeWidgetYs.clear();
	}

	private static class ClanPlayerRow
	{
		private final int rowIndex;
		private final List<Widget> widgets = new ArrayList<>();
		private ClanChannelMember member;

		private ClanPlayerRow(int rowIndex)
		{
			this.rowIndex = rowIndex;
		}
	}
}

package com.clanqol.clanpanel;

import java.time.DateTimeException;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

// validates/normalizes timezone input and formats the current time for a stored zone id
public final class ClanTimezones
{
    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("HH:mm");
    private static final Map<String, String> IANA_IDS_LOWER = buildIanaIndex();
    private static final Map<String, String> SHORT_CODES = buildShortCodes();

    private ClanTimezones()
    {
    }

    public static String normalize(String input)
    {
        if (input == null || input.trim().isEmpty())
        {
            return null;
        }

        String trimmed = input.trim();
        String upper = trimmed.toUpperCase();

        String curated = SHORT_CODES.get(upper);
        if (curated != null)
        {
            return curated;
        }

        String iana = IANA_IDS_LOWER.get(trimmed.toLowerCase());
        if (iana != null)
        {
            return iana;
        }

        if (ZoneId.SHORT_IDS.containsKey(upper))
        {
            try
            {
                return ZoneId.of(upper, ZoneId.SHORT_IDS).getId();
            }
            catch (DateTimeException ignored)
            {
            }
        }

        try
        {
            return ZoneId.of(normalizeOffsetCasing(trimmed)).getId();
        }
        catch (DateTimeException ignored)
        {
            return null;
        }
    }

    static boolean isValid(String input)
    {
        return normalize(input) != null;
    }

    // formats the current time for zone id like "14:32"
    static String currentTime(String zoneId)
    {
        try
        {
            return ZonedDateTime.now(ZoneId.of(zoneId)).format(TIME_FORMAT);
        }
        catch (DateTimeException e)
        {
            return null;
        }
    }

    // only uppercases the UTC/GMT/Z
    private static String normalizeOffsetCasing(String input)
    {
        String upper = input.toUpperCase();
        if (upper.startsWith("UTC") || upper.startsWith("GMT") || upper.equals("UT") || upper.equals("Z"))
        {
            return upper;
        }

        return input;
    }

    private static Map<String, String> buildIanaIndex()
    {
        Map<String, String> index = new HashMap<>();
        for (String id : ZoneId.getAvailableZoneIds())
        {
            index.put(id.toLowerCase(), id);
        }

        return Collections.unmodifiableMap(index);
    }

    private static Map<String, String> buildShortCodes()
    {
        Map<String, String> map = new HashMap<>();

        // US
        map.put("EST", "America/New_York");
        map.put("EDT", "America/New_York");
        map.put("CST", "America/Chicago");
        map.put("CDT", "America/Chicago");
        map.put("MST", "America/Denver");
        map.put("MDT", "America/Denver");
        map.put("PST", "America/Los_Angeles");
        map.put("PDT", "America/Los_Angeles");
        map.put("AKST", "America/Anchorage");
        map.put("AKDT", "America/Anchorage");
        map.put("HST", "Pacific/Honolulu");

        // Australia
        map.put("AEST", "Australia/Sydney");
        map.put("AEDT", "Australia/Sydney");
        map.put("ACST", "Australia/Adelaide");
        map.put("ACDT", "Australia/Adelaide");
        map.put("AWST", "Australia/Perth");

        // Europe - covers the EU's three DST-observing zones plus UK and Russia
        map.put("GMT", "Europe/London");
        map.put("BST", "Europe/London");
        map.put("WET", "Europe/Lisbon");
        map.put("WEST", "Europe/Lisbon");
        map.put("CET", "Europe/Paris");
        map.put("CEST", "Europe/Paris");
        map.put("EET", "Europe/Helsinki");
        map.put("EEST", "Europe/Helsinki");
        map.put("MSK", "Europe/Moscow");

        return Collections.unmodifiableMap(map);
    }
}

package com.clanqol.utils;

import com.clanqol.ClanQolConfig;
import com.clanqol.clanpanel.ClanCountryFlags;
import com.clanqol.clanpanel.ClanTimezones;
import com.google.common.base.Strings;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.config.ConfigManager;

// keeps the csvData config box in sync with username/note/flag/timezone format
public final class ClanCsvSync
{
    public static final String CSV_KEY = "csvData";

    private static final String NOTE_PREFIX = "note_";
    private static final String FLAG_PREFIX = "flag_";
    private static final String TIMEZONE_PREFIX = "timezone_";

    private ClanCsvSync()
    {
    }

    public static final class Result
    {
        public int applied;
        public final List<String> errors = new ArrayList<>();
    }

    public static String build(ConfigManager configManager)
    {
        List<String> names = new ArrayList<>(collectAllNames(configManager));
        names.sort(String.CASE_INSENSITIVE_ORDER);

        List<String> lines = new ArrayList<>();
        for (String name : names)
        {
            lines.add(encodeLine(name,
                    read(configManager, FLAG_PREFIX, name),
                    read(configManager, TIMEZONE_PREFIX, name),
                    read(configManager, NOTE_PREFIX, name)));
        }

        return String.join("\n", lines);
    }

    public static Result apply(ConfigManager configManager, String csv, boolean replace)
    {
        Result result = new Result();
        Set<String> seen = new HashSet<>();

        for (String rawLine : csv.split("\\r?\\n"))
        {
            String line = rawLine.trim();
            if (line.isEmpty())
            {
                continue;
            }

            List<String> fields = decodeLine(line);
            String name = fields.get(0).trim();
            if (name.isEmpty())
            {
                continue;
            }

            seen.add(name);
            String flag = fields.size() > 1 ? fields.get(1).trim().toUpperCase() : "";
            String timezone = fields.size() > 2 ? fields.get(2).trim() : "";
            String note = fields.size() > 3 ? fields.get(3).trim() : "";

            if (flag.isEmpty())
            {
                if (replace)
                {
                    remove(configManager, FLAG_PREFIX + name);
                }
            }
            else if (ClanCountryFlags.isValidCode(flag))
            {
                put(configManager, FLAG_PREFIX + name, flag);
            }
            else
            {
                result.errors.add("invalid flag '" + flag + "' for " + name);
            }

            if (timezone.isEmpty())
            {
                if (replace)
                {
                    remove(configManager, TIMEZONE_PREFIX + name);
                }
            }
            else
            {
                String normalized = ClanTimezones.normalize(timezone);
                if (normalized != null)
                {
                    put(configManager, TIMEZONE_PREFIX + name, normalized);
                }
                else
                {
                    result.errors.add("invalid timezone '" + timezone + "' for " + name);
                }
            }

            if (note.isEmpty())
            {
                if (replace)
                {
                    remove(configManager, NOTE_PREFIX + name);
                }
            }
            else
            {
                put(configManager, NOTE_PREFIX + name, note);
            }

            result.applied++;
        }

        if (replace)
        {
            for (String name : collectAllNames(configManager))
            {
                if (!seen.contains(name))
                {
                    remove(configManager, NOTE_PREFIX + name);
                    remove(configManager, FLAG_PREFIX + name);
                    remove(configManager, TIMEZONE_PREFIX + name);
                }
            }
        }

        return result;
    }

    // rewrites the config box from stored data or doing nothing if completly matches
    public static void syncField(ConfigManager configManager)
    {
        String built = build(configManager);
        String current = Strings.nullToEmpty(configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, CSV_KEY));
        if (!built.equals(current))
        {
            configManager.setConfiguration(ClanQolConfig.CONFIG_GROUP, CSV_KEY, built);
        }
    }

    private static Set<String> collectAllNames(ConfigManager configManager)
    {
        Set<String> names = new HashSet<>();
        collectNames(configManager, names, NOTE_PREFIX);
        collectNames(configManager, names, FLAG_PREFIX);
        collectNames(configManager, names, TIMEZONE_PREFIX);
        return names;
    }

    private static void collectNames(ConfigManager configManager, Set<String> names, String keyPrefix)
    {
        String fullPrefix = ClanQolConfig.CONFIG_GROUP + "." + keyPrefix;
        for (String fullKey : configManager.getConfigurationKeys(fullPrefix))
        {
            names.add(fullKey.substring(fullPrefix.length()));
        }
    }

    private static String read(ConfigManager configManager, String keyPrefix, String name)
    {
        return Strings.nullToEmpty(configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, keyPrefix + name));
    }

    private static void put(ConfigManager configManager, String key, String value)
    {
        if (!value.equals(configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, key)))
        {
            configManager.setConfiguration(ClanQolConfig.CONFIG_GROUP, key, value);
        }
    }

    private static void remove(ConfigManager configManager, String key)
    {
        if (configManager.getConfiguration(ClanQolConfig.CONFIG_GROUP, key) != null)
        {
            configManager.unsetConfiguration(ClanQolConfig.CONFIG_GROUP, key);
        }
    }

    private static String encodeLine(String... fields)
    {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < fields.length; i++)
        {
            if (i > 0)
            {
                sb.append(',');
            }
            sb.append(encodeField(fields[i]));
        }
        return sb.toString();
    }

    // fields with commas or quotes get wrapped in quotes, inner quotes doubled
    private static String encodeField(String field)
    {
        if (field == null || field.isEmpty())
        {
            return "";
        }

        boolean needsQuoting = field.contains(",") || field.contains("\"");
        return needsQuoting ? "\"" + field.replace("\"", "\"\"") + "\"" : field;
    }

    private static List<String> decodeLine(String line)
    {
        List<String> fields = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;

        for (int i = 0; i < line.length(); i++)
        {
            char c = line.charAt(i);

            if (inQuotes)
            {
                if (c == '"')
                {
                    if (i + 1 < line.length() && line.charAt(i + 1) == '"')
                    {
                        current.append('"');
                        i++;
                    }
                    else
                    {
                        inQuotes = false;
                    }
                }
                else
                {
                    current.append(c);
                }
            }
            else if (c == '"')
            {
                inQuotes = true;
            }
            else if (c == ',')
            {
                fields.add(current.toString());
                current.setLength(0);
            }
            else
            {
                current.append(c);
            }
        }

        fields.add(current.toString());
        return fields;
    }
}

package com.clanqol.utils;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Point;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

// shared row-matching helpers for the clan player list widget, used by both the note/flag
// overlay and the right-click menu resolver so the grouping/matching logic only lives once
public final class ClanPlayerListRows
{
	private static final int ROW_HEIGHT = 15;

	public ClanPlayerListRows()
	{
	}

	public static Map<Integer, List<Widget>> groupByRow(Widget[] children)
	{
		Map<Integer, List<Widget>> rowsByIndex = new HashMap<>();
		for (Widget child : children)
		{
			if (child == null || child.isHidden())
			{
				continue;
			}

			int rowIndex = Math.round(child.getOriginalY() / (float) ROW_HEIGHT);
			rowsByIndex.computeIfAbsent(rowIndex, k -> new ArrayList<>()).add(child);
		}

		return rowsByIndex;
	}

	public static Map<String, ClanChannelMember> mapMembersByName(ClanChannel clanChannel)
	{
		Map<String, ClanChannelMember> membersByName = new HashMap<>();
		for (ClanChannelMember member : clanChannel.getMembers())
		{
			membersByName.put(normalize(member.getName()), member);
		}

		return membersByName;
	}

	public static ClanChannelMember findMember(List<Widget> rowWidgets, Map<String, ClanChannelMember> membersByName)
	{
		for (Widget widget : rowWidgets)
		{
			ClanChannelMember member = membersByName.get(normalize(widget.getText()));
			if (member != null)
			{
				return member;
			}

			member = membersByName.get(normalize(widget.getName()));
			if (member != null)
			{
				return member;
			}
		}

		return null;
	}

	public static boolean isRowAtPoint(List<Widget> rowWidgets, Point point)
	{
		for (Widget widget : rowWidgets)
		{
			Rectangle bounds = widget.getBounds();
			if (bounds != null && bounds.contains(point.getX(), point.getY()))
			{
				return true;
			}
		}

		return false;
	}

	static String normalize(String name)
	{
		return name == null ? "" : Text.toJagexName(Text.removeTags(name)).toLowerCase();
	}
}

package com.clanqol.utils;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;

import java.util.function.BooleanSupplier;

@Slf4j
public class ClanSortToggleButton
{
	// carried over from Sight's sprite ids. havent independently confirmed
	// which one actually looks like an up vs down triangle, swap these two
	// if the icon looks backwards in game
	private static final int SPRITE_ASCENDING = 1051;
	private static final int SPRITE_DESCENDING = 1050;

	private static final int BUTTON_WIDTH = 8;
	private static final int BUTTON_HEIGHT = 8;

	private final Client client;
	private final ClientThread clientThread;
	private final int x;
	private final int y;
	private final String sortAscendingTooltip;
	private final String sortDescendingTooltip;
	private final BooleanSupplier isAscending;
	private final Runnable onAscendingClick;
	private final Runnable onDescendingClick;

	private Widget button;
	private Widget parentAtCreation;

	// isAscending should return true when this column's ascending mode is the
	// sorter's current mode. onAscendingClick/onDescendingClick should call
	// the sorter's matching setX methods
	public ClanSortToggleButton(Client client, ClientThread clientThread, int x, int y,
								String sortAscendingTooltip, String sortDescendingTooltip,
								BooleanSupplier isAscending, Runnable onAscendingClick, Runnable onDescendingClick)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.x = x;
		this.y = y;
		this.sortAscendingTooltip = sortAscendingTooltip;
		this.sortDescendingTooltip = sortDescendingTooltip;
		this.isAscending = isAscending;
		this.onAscendingClick = onAscendingClick;
		this.onDescendingClick = onDescendingClick;
	}

	// call once from startUp. panel probably isnt open yet so schedule it
	public void startUp()
	{
		clientThread.invokeLater(this::createButton);
	}

	// call from onGameTick amd recreates the button if the panel got closed and reopened
	public void onGameTick()
	{
		Widget currentParent = client.getWidget(InterfaceID.ClansSidepanel.UNIVERSE);

		if (currentParent == null)
		{
			// panel not open, drop stale refs so we rebuild cleanly once it
			// reopens
			button = null;
			parentAtCreation = null;
			return;
		}

		if (button == null || currentParent != parentAtCreation)
		{
			createButton();
			return;
		}

		syncButton();
	}

	// call from shutDown
	public void reset()
	{
		hideButton();
		parentAtCreation = null;
	}

	private void createButton()
	{
		Widget parent = client.getWidget(InterfaceID.ClansSidepanel.UNIVERSE);
		if (parent == null)
		{
			button = null;
			parentAtCreation = null;
			return;
		}

		hideButton();

		button = parent.createChild(-1, WidgetType.GRAPHIC);
		button.setOriginalWidth(BUTTON_WIDTH);
		button.setOriginalHeight(BUTTON_HEIGHT);
		button.setOriginalX(x);
		button.setOriginalY(y);
		button.setOnOpListener((JavaScriptCallback) ev -> clientThread.invokeLater(this::handleClick));
		button.setHasListener(true);
		button.revalidate();

		parentAtCreation = parent;

		syncButton();
	}

	private void handleClick()
	{
		if (isAscending.getAsBoolean())
		{
			onDescendingClick.run();
		}
		else
		{
			onAscendingClick.run();
		}

		syncButton();
	}

	private void syncButton()
	{
		if (button == null)
		{
			return;
		}

		boolean ascendingActive = isAscending.getAsBoolean();
		button.setSpriteId(ascendingActive ? SPRITE_ASCENDING : SPRITE_DESCENDING);
		button.setAction(0, ascendingActive ? sortDescendingTooltip : sortAscendingTooltip);
	}

	private void hideButton()
	{
		if (button == null)
		{
			return;
		}

		button.setHidden(true);
		button = null;
	}
}

